function decodeLand(packed: string) {
  const raw = atob(packed.replace(/\s/g, ""));
  const bytes = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
  return bytes;
}

export const landMask = decodeLand(landPacked);
